function reverseKGroup(head, k) {
    if (!head || k === 1) {
        return head;
    }

    let dummy = { val: 0, next: head };
    let prevGroupEnd = dummy; // Node before the current k-group

    while (true) {
        let groupStart = prevGroupEnd.next;
        if (!groupStart) { // No more nodes
            break;
        }

        // 1. Find the k-th node of the current group
        let groupEnd = groupStart;
        for (let i = 1; i < k; i++) {
            if (!groupEnd) {
                break;
            }
            groupEnd = groupEnd.next;
        }

        if (!groupEnd) { // Not enough nodes, remaining list is not reversed
            break;
        }

        // 2. Store next_group_start
        let nextGroupStart = groupEnd.next;

        // 3. Cut the k-group
        groupEnd.next = null;

        // 4. Reverse the k-group (from groupStart to groupEnd)
        let reversedHead = reverseList(groupStart);

        // 5. Connect previous group to reversed group
        prevGroupEnd.next = reversedHead;

        // 6. Connect reversed group tail to next group
        groupStart.next = nextGroupStart; // groupStart is now the tail of the reversed group

        // 7. Update prevGroupEnd for the next iteration
        prevGroupEnd = groupStart;
    }

    return dummy.next;
}

// Helper function to reverse a standard linked list
function reverseList(head) {
    let prev = null;
    let curr = head;
    while (curr) {
        let nextTemp = curr.next;
        curr.next = prev;
        prev = curr;
        curr = nextTemp;
    }
    return prev;
}
